/**
 * Hero-vs-hero numbers from public matches at the player's own rank
 * (data/matchups-rank.json from STRATZ, regenerated by
 * scripts/coach-matchups-rank.mjs). Pure lookups: the engine never fetches.
 *
 * Every number carries its sample and its source, and the STRATZ credit
 * travels with it (RANK_SOURCE.attribution). Verdicts follow the same rule
 * as the pro baselines in matchups.js: no claim on noise.
 * - Win rate: 100+ games, and at least two standard errors from the hero's
 *   own win rate in that bracket.
 * - Lane: 50+ lanes, and the won-minus-lost share (stomps included) at least
 *   5 points and two standard errors from the hero's own share over all its
 *   lanes in that bracket. Against zero it would only restate the role: an
 *   offlaner loses most lanes to any safe-lane carry.
 * Too few games is null, never "even".
 *
 * Kept out of goals.js / knowledge.js: the web client bundles those, and
 * this table is server-side data.
 */
import { createRequire } from 'node:module';

const R = createRequire(import.meta.url)('./data/matchups-rank.json');

export const RANK_SOURCE = Object.freeze({
  source: R.source, attribution: R.attribution, patch: R.patch, weeks: R.weeks, fetched: R.fetched, games: R.games,
});

/** Bracket keys, lowest first, with their labels. */
export const BRACKET_LABEL = Object.freeze({
  hg: { en: 'Herald–Guardian', zh: '先锋–卫士' },
  ca: { en: 'Crusader–Archon', zh: '中军–统帅' },
  la: { en: 'Legend–Ancient', zh: '传奇–万古' },
  di: { en: 'Divine–Immortal', zh: '超凡–冠绝' },
});
export const BRACKETS = Object.freeze(Object.keys(BRACKET_LABEL));

const VS_MIN = 100;
const LANE_MIN = 50;
const LANE_MIN_GAP = 0.05;

/** OpenDota rank_tier (tens digit 1 Herald … 8 Immortal) → bracket key, or null. */
export function bracketOfTier(rankTier) {
  const medal = Math.floor(Number(rankTier) / 10);
  if (!Number.isInteger(medal) || medal < 1 || medal > 8) return null;
  return BRACKETS[Math.floor((medal - 1) / 2)];
}

/** "hg" | "Legend" | 54 → bracket key, or null. */
export function parseBracket(x) {
  if (x == null || x === '') return null;
  const s = String(x).trim().toLowerCase();
  if (BRACKETS.includes(s)) return s;
  if (/^\d{1,2}$/.test(s)) return bracketOfTier(Number(s) < 10 ? Number(s) * 10 : Number(s));
  const MEDALS = ['herald', 'guardian', 'crusader', 'archon', 'legend', 'ancient', 'divine', 'immortal'];
  const i = MEDALS.indexOf(s);
  return i >= 0 ? BRACKETS[Math.floor(i / 2)] : null;
}

/**
 * The bracket a review is read against: the player's own medal when public,
 * else the median of the medals that are public in that match (3+ needed).
 * @param {{ rank_tier?: number|null }[]} players  OpenDota match players
 * @param {{ rank_tier?: number|null }} me
 * @returns {null | { key: string, basis: 'player' | 'match', known: number }}
 */
export function reviewBracket(players, me) {
  const own = bracketOfTier(me?.rank_tier);
  if (own) return { key: own, basis: 'player', known: 1 };
  const tiers = (players ?? []).map((p) => p?.rank_tier).filter((t) => bracketOfTier(t)).sort((a, b) => a - b);
  if (tiers.length < 3) return null;
  return { key: bracketOfTier(tiers[Math.floor((tiers.length - 1) / 2)]), basis: 'match', known: tiers.length };
}

/**
 * h's win rate with v on the enemy team in bracket b, against h's own.
 * @returns {null | { bracket: string, n: number, wr: number, base: number, diff: number, verdict: 'favoured'|'unfavoured'|'even' }}
 */
export function heroVsRank(h, v, b) {
  const row = R.vs?.[b]?.[h]?.[v];
  const bs = R.base?.[b]?.[h];
  if (!row || !bs || row[0] < VS_MIN || !bs[0]) return null;
  const [n, w] = row;
  const wr = w / n;
  const base = bs[1] / bs[0];
  const se = Math.sqrt((base * (1 - base)) / n);
  const diff = wr - base;
  return { bracket: b, n, wr, base, diff, verdict: Math.abs(diff) >= 2 * se ? (diff > 0 ? 'favoured' : 'unfavoured') : 'even' };
}

const laneBaseCache = new Map();
/** h's lanes against everyone in bracket b: { won, lost, edge } shares, or null. */
function laneBase(h, b) {
  const key = `${b}:${h}`;
  if (!laneBaseCache.has(key)) {
    let W = 0; let L = 0; let n = 0;
    for (const [w, d, l, sw, sl] of Object.values(R.lane?.[b]?.[h] ?? {})) { W += w + sw; L += l + sl; n += w + d + l + sw + sl; }
    laneBaseCache.set(key, n ? { won: W / n, lost: L / n, edge: (W - L) / n } : null);
  }
  return laneBaseCache.get(key);
}

/**
 * Lanes where h laned against v in bracket b (h's side of the outcome),
 * judged against h's own lanes in that bracket (`base`).
 * @returns {null | { bracket: string, n: number, won: number, even: number, lost: number, stomped: number, edge: number, base: { won: number, lost: number, edge: number }, verdict: 'favoured'|'unfavoured'|'even' }}
 */
export function laneVsRank(h, v, b) {
  const row = R.lane?.[b]?.[h]?.[v];
  const base = laneBase(h, b);
  if (!row || !base) return null;
  // Five disjoint outcomes (a stomp is not also a win or a loss).
  const [W, D, L, SW, SL] = row;
  const n = W + D + L + SW + SL;
  if (n < LANE_MIN) return null;
  const pw = (W + SW) / n; const pl = (L + SL) / n;
  const edge = pw - pl;
  const se = Math.sqrt(Math.max(0, pw + pl - edge * edge) / n);
  const gap = edge - base.edge;
  const real = Math.abs(gap) >= LANE_MIN_GAP && Math.abs(gap) >= 2 * se;
  return { bracket: b, n, won: pw, even: D / n, lost: pl, stomped: SL / n, edge, base, verdict: real ? (gap > 0 ? 'favoured' : 'unfavoured') : 'even' };
}

const pctS = (x) => `${Math.round(x * 100)}%`;
const fmtN = (n) => n.toLocaleString('en-US');
/** "Legend–Ancient public games, 7.41 (4 weeks to 2026-11-15, STRATZ)" */
function scope(b, lang) {
  const w = R.weeks;
  return lang === 'zh'
    ? `${BRACKET_LABEL[b].zh}路人局（${R.patch}，截至 ${w.to} 的 ${w.count} 周，数据来自 STRATZ）`
    : `${BRACKET_LABEL[b].en} public games (${R.patch}, ${w.count} weeks to ${w.to}, data: STRATZ)`;
}

/** The lane numbers as one bilingual evidence line. */
export function rankLaneLine(hero, vs, lr) {
  return {
    en: `${scope(lr.bracket, 'en')}, ${hero.en} laning against ${vs.en}: won ${pctS(lr.won)}, even ${pctS(lr.even)}, lost ${pctS(lr.lost)} (stomped ${pctS(lr.stomped)}) of ${fmtN(lr.n)} lanes; all ${hero.en} lanes: won ${pctS(lr.base.won)}, lost ${pctS(lr.base.lost)}`,
    zh: `${scope(lr.bracket, 'zh')}，${hero.zh}与${vs.zh}同线对线：赢 ${pctS(lr.won)}、平 ${pctS(lr.even)}、输 ${pctS(lr.lost)}（被打崩 ${pctS(lr.stomped)}），共 ${fmtN(lr.n)} 条线；${hero.zh}所有对线：赢 ${pctS(lr.base.won)}、输 ${pctS(lr.base.lost)}`,
  };
}

/** The win-rate numbers as one bilingual line. */
export function rankVsLine(hero, vs, m) {
  return {
    en: `${scope(m.bracket, 'en')}: ${hero.en} wins ${pctS(m.wr)} against ${vs.en} (${fmtN(m.n)} games; ${pctS(m.base)} overall)`,
    zh: `${scope(m.bracket, 'zh')}：${hero.zh}对上${vs.zh}胜率 ${pctS(m.wr)}（${fmtN(m.n)} 场；平时 ${pctS(m.base)}）`,
  };
}
